  %sel = select i1 %cmp, float 0.000000e+00, float 0.000000e+00
  ret float %sel
}

Target:
define float @test_select_nnan_nsz_fcmp_olt(float %x) {
  ret float %x
}

Transformation doesn't verify!

ERROR: Value mismatch

Example:
float %x = #x00000001 (0.000000000000?)

Source:
i1 %cmp = #x0 (0)
float %sel = #x00000000 (+0.0)

Target:
Source value: #x00000000 (+0.0)
Target value: #x00000001 (0.000000000000?)

